import * as React from "react"
import { cn } from "@/lib/utils"

export interface NumericInputProps extends Omit<React.ComponentProps<"input">, "type"> {
  icon?: React.ReactNode;
  iconPosition?: "left" | "right";
}

const NumericInput = React.forwardRef<HTMLInputElement, NumericInputProps>(
  ({ className, icon, iconPosition = "left", onChange, onKeyDown, ...props }, ref) => {

    // Prevent non-numeric key strokes while typing
    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
      const allowedKeys = [
        "Backspace", "Delete", "Tab", "Escape", "Enter", "ArrowLeft", "ArrowRight", "End", "Home", "."
      ];

      // Allow only digits and specified special keys
      if (!/[0-9]/.test(e.key) && !allowedKeys.includes(e.key)) {
        e.preventDefault();
      }

      // Allow only one decimal point
      if (e.key === "." && e.currentTarget.value.includes(".")) {
        e.preventDefault();
      }

      // Propagate the original onKeyDown event if it exists
      if (onKeyDown) onKeyDown(e);
    };

    // Sanitize input to prevent pasted non-numeric values or multiple dots
    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      let value = e.target.value;

      // Remove all characters except digits and the first decimal point
      value = value.replace(/[^0-9.]/g, "");
      const dotCount = (value.match(/\./g) || []).length;
      if (dotCount > 1) {
        const parts = value.split(".");
        value = parts[0] + "." + parts.slice(1).join("");
      }

      // Update the event's target value so the parent's onChange works as expected
      e.target.value = value;
      if (onChange) onChange(e);
    };

    return (
      <div className="relative group/numeric w-full">
        {icon && iconPosition === "left" && (
          <div className="absolute left-3 top-1/2 -translate-y-1/2 flex items-center justify-center text-muted-foreground transition-colors group-focus-within/numeric:text-primary">
            {icon}
          </div>
        )}

        <input
          {...props}
          ref={ref}
          type="text"
          inputMode="decimal"
          onKeyDown={handleKeyDown}
          onChange={handleChange}
          className={cn(
            "h-8 w-full min-w-0 rounded-lg border border-input bg-transparent py-1 text-base transition-colors outline-none",
            "placeholder:text-muted-foreground focus-visible:border-ring",
            "disabled:pointer-events-none disabled:cursor-not-allowed disabled:bg-input/50 disabled:opacity-50",
            "aria-invalid:border-destructive md:text-sm",
            "dark:bg-input/30 dark:disabled:bg-input/80 dark:aria-invalid:border-destructive/50",
            // Hide spin buttons for browsers that might try to show them
            "[&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none appearance-none",
            // Padding based on icon presence
            icon ? (iconPosition === "left" ? "pl-9 pr-2.5" : "pr-9 pl-2.5") : "px-2.5",
            className
          )}
        />

        {icon && iconPosition === "right" && (
          <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center justify-center text-muted-foreground transition-colors group-focus-within/numeric:text-primary">
            {icon}
          </div>
        )}
      </div>
    );
  }
)

NumericInput.displayName = "NumericInput"

export { NumericInput }
